style.css:
/* --- CONFIGURATION LAYER --- */
  :root {
    /* 1. Put your image link between the quotes below */
    --custom-bg-image: url(https://i.pinimg.com/736x/4e/fc/ab/4efcab9169832f56592de48273bf749b.jpg);
    
    /* 2. Soft off-white colors optimized for high contrast on dark backgrounds */
    --text-normal: #e3e3e6 !important;       /* Main chat text (soft white) */
    --text-muted: #a6a7ab !important;        /* Timestamps and secondary labels (light gray) */
    --header-primary: #ffffff !important;    /* Server titles and section headers (pure white) */
    --channels-default: #b9bbbe !important;  /* Sidebar channel names (muted silver) */
    
    /* 3. Subtle overlay to keep text perfectly sharp against the shiny details of the lilies */
    --background-overlay: rgba(0, 0, 0, 0.4); 
  }
